local MODE = "ROLLBACK"
local DATA = game:GetService("HttpService"):JSONDecode([==[{"attributes": [{"before": "", "key": "TurboWhistleAssetId", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "rbxassetid://126900976760387"}, {"before": 36, "key": "ProfileRevision", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 37}, {"key": "RpmRevEnabled", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1}, {"key": "RpmRevEnabled_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Switch (0/1). 1: while the car's gearbox runs, the engine voice follows its rpm (gears, shifts, limiter). 0: the old speed-shaped rev for every car and none of the gearbox sounds."}, {"key": "RevRpmMin", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1000}, {"key": "RevRpmMin_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Engine rpm placed at the bottom of the rev-layer range. Raising it lowers every pitch at a given rpm (idle sounds deeper); keep it near the idle rpm."}, {"key": "RevRpmMax", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 8600}, {"key": "RevRpmMax_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Engine rpm placed at the top of the rev-layer range when RevRpmMaxFromCar is 0 (or the car gives no limiter). Raising it lowers the pitch at every rpm, so redline sounds less screaming; lowering it pushes the top loops higher."}, {"key": "RevRpmMaxFromCar", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1}, {"key": "RevRpmMaxFromCar_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Switch (0/1). 1: the top of the rev-layer range is the car's own limiter rpm (Drivetrain.<class>@LimiterRpm, via FeelLimiterRpm or GearForSpeed), so retuning the limiter keeps redline at the top loop. 0: RevRpmMax is used for every car."}, {"key": "RevRpmSmoothingSeconds", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.02}, {"key": "RevRpmSmoothingSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Time constant (s) the engine pitch takes to follow rpm. Raising it softens and blurs revs, blips and shifts; near 0 the pitch tracks rpm exactly."}, {"key": "RemoteRevSmoothingSeconds", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.06}, {"key": "RemoteRevSmoothingSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Time constant (s) for other players' cars, which update at 15 Hz. Raising it glides their shifts more; lowering it makes their rpm drops step."}, {"key": "ShiftAudioEnabled", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1}, {"key": "ShiftAudioEnabled_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Switch (0/1). 1: shifts drop the rev, dip the volume, blip on downshifts, clunk and vent. 0: the pitch just follows rpm with no shift effects (the reactor chirp has its own switch)."}, {"key": "ShiftDropSeconds", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.035}, {"key": "ShiftDropSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "How long (s) an upshift takes to fall to the new gear's rpm. Raising it makes upshifts slurred and lazy; lowering it makes them snap like a fast dual-clutch. Without a predicted landing it can fall no faster than the engine rpm itself. Needs ShiftDropMaxSeconds above 0."}, {"key": "ShiftDropMaxSeconds", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.25}, {"key": "ShiftDropMaxSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Longest time (s) the upshift drop may run; it also ends as soon as the engine rpm stops falling. Raising it allows longer drops on slow shifts; 0 turns the drop shaping off, so the pitch follows FeelRpm down with RevRpmSmoothingSeconds and ShiftDropSeconds does nothing."}, {"key": "ShiftDipDb", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 5}, {"key": "ShiftDipDb_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Engine volume dip (dB) during an upshift cut at full strength. Raising it makes each upshift a harder, more obvious gap; 0 removes the dip."}, {"key": "ShiftDipMinSeconds", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.07}, {"key": "ShiftDipMinSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Shortest upshift dip (s), so a 30 Hz phone update still shows it. Raising it lengthens every dip; 0 lets the dip end as soon as the cut ends."}, {"key": "ShiftDipMaxSeconds", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.25}, {"key": "ShiftDipMaxSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Longest upshift dip (s) even if the cut stays on. Raising it allows longer gaps on slow shifts; lowering it caps the gap."}, {"key": "ShiftDipAttackSeconds", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.008}, {"key": "ShiftDipAttackSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "How fast (s) the volume falls into the dip. Raising it softens the start of the gap; lowering it makes it a sharp cut."}, {"key": "ShiftDipReleaseSeconds", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.05}, {"key": "ShiftDipReleaseSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "How fast (s) the volume returns after the dip. Raising it makes the engine swell back in slowly; lowering it snaps it back."}, {"key": "DownshiftBlipRev", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.08}, {"key": "DownshiftBlipRev_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Extra rev (0..1 of the range) added by the throttle blip on each downshift. Raising it gives a louder, higher rev-match bark; 0 removes the blip."}, {"key": "DownshiftBlipSeconds", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.12}, {"key": "DownshiftBlipSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Length (s) of the downshift blip. Raising it makes a longer, lazier blip; lowering it makes a short stab."}, {"key": "DownshiftBlipLoad", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1}, {"key": "DownshiftBlipLoad_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Engine load (0..1) forced during the blip, so the tip-in bark fires. Raising it makes the blip sound on-throttle and barky; 0 keeps the blip on the coast sound."}, {"key": "ShiftCrackleEnabled", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1}, {"key": "ShiftCrackleEnabled_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Switch (0/1). 1: a hard upshift (strength at or above Config.Vehicles.StabiliserVFX@ShiftVentMinStrength, the vent flame's threshold) with no ShiftVent sound fires one exhaust pop directly (never through FeelPopRevision). 0: no crackle on upshifts."}, {"key": "ShiftCracklePop", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.55}, {"key": "ShiftCracklePop_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Strength (0..1) of that upshift crackle pop. Raising it makes it louder; at 0.8 or more it becomes a bang. 0 is silent."}, {"key": "ShiftPitchJitter", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.03}, {"key": "ShiftPitchJitter_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Random pitch spread (fraction) of the shift clunk and vent. Raising it makes repeated shifts sound less identical; 0 plays them the same every time."}, {"key": "EngineBusEnabled", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1}, {"key": "EngineBusEnabled_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Switch (0/1). 1: the player's own engine runs through a small effects bus (load sweep, EQ tilt, limiter stutter, shift dip). 0: no bus is built; the engine is wired straight out as before and the dip goes on the voices."}, {"key": "EngineSweepLowHz", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 350}, {"key": "EngineSweepLowHz_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Centre (Hz) of the resonant peak with no load. Raising it moves the off-throttle resonance up into a nasal honk; lowering it puts it into the body."}, {"key": "EngineSweepHighHz", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 2600}, {"key": "EngineSweepHighHz_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Centre (Hz) of the resonant peak at full load and rpm. Raising it gives a brighter, more screaming sweep under throttle; lowering it keeps the sweep throaty."}, {"key": "EngineSweepRevShare", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.4}, {"key": "EngineSweepRevShare_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Share (0..1) of the sweep position that comes from rpm rather than load. Raising it makes the resonance climb through each gear; 0 makes it follow the throttle only."}, {"key": "EngineSweepDb", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 3}, {"key": "EngineSweepDb_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Height (dB) of the resonant peak at full load. Raising it makes the sweep a strong wah; 0 removes it."}, {"key": "EngineSweepQ", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1.6}, {"key": "EngineSweepQ_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Sharpness of the resonant peak. Raising it makes a narrow, whistling resonance; lowering it makes a broad, gentle colour."}, {"key": "EngineTiltLowOffDb", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": -1}, {"key": "EngineTiltLowOffDb_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Low band (dB) on overrun. Raising it keeps more body when coasting; lowering it thins the overrun."}, {"key": "EngineTiltLowOnDb", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 2}, {"key": "EngineTiltLowOnDb_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Low band (dB) at full load. Raising it makes full throttle heavier and boomier; 0 adds no weight."}, {"key": "EngineTiltMidOffDb", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": -0.5}, {"key": "EngineTiltMidOffDb_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Mid band (dB) on overrun. Raising it keeps more rasp when coasting; lowering it softens the overrun."}, {"key": "EngineTiltMidOnDb", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1.5}, {"key": "EngineTiltMidOnDb_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Mid band (dB) at full load, where the grit sits. Raising it makes full throttle grittier and more forward; 0 adds none."}, {"key": "EngineTiltHighOffDb", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": -4}, {"key": "EngineTiltHighOffDb_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "High band (dB) on overrun. Raising it keeps the overrun bright; lowering it muffles the engine more when you lift."}, {"key": "EngineTiltHighOnDb", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0}, {"key": "EngineTiltHighOnDb_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "High band (dB) at full load. Raising it adds fizz and edge under throttle; lowering it darkens full throttle."}, {"key": "LimiterTremoloEnabled", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1}, {"key": "LimiterTremoloEnabled_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Switch (0/1). 1: bouncing off the limiter stutters the engine (tremolo on the bus). 0: no stutter (the rpm still bounces)."}, {"key": "LimiterNearRpm", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 200}, {"key": "LimiterNearRpm_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "How close (rpm) to the limiter the stutter may start. Raising it lets the stutter begin earlier; 0 needs the rpm at the limiter itself."}, {"key": "LimiterHoldSeconds", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.1}, {"key": "LimiterHoldSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "How long (s) the stutter stays on after the last limiter bounce, so it does not flicker. Raising it keeps it going longer; 0 follows each cut only."}, {"key": "LimiterTremoloHz", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 13.3}, {"key": "LimiterTremoloHz_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Stutter rate (Hz); 13.3 matches the default limiter cycle (0.03 s on, 0.045 s cut). Raising it buzzes faster; lowering it chops slower."}, {"key": "LimiterTremoloDepth", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.7}, {"key": "LimiterTremoloDepth_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "How deep (0..1) each stutter dip goes. Raising it makes a harder on-off bounce; 0 is no stutter."}, {"key": "LimiterTremoloDuty", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.4}, {"key": "LimiterTremoloDuty_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Share (0..1) of each stutter cycle spent at full volume (0.4 = the default limiter on-time share). Raising it makes the gaps shorter."}, {"key": "LimiterTremoloSquare", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.6}, {"key": "LimiterTremoloSquare_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "How square (0..1) the stutter wave is. Raising it makes a choppier, harder gate; 0 is a smooth wobble."}, {"key": "ReactorEnabled", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1}, {"key": "ReactorEnabled_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Switch (0/1). 1: the TurboWhistle slot (TurboWhistleAssetId, now turbine_high) is the reactor whine that follows road speed, silent unless the gearbox runs; TurboWhistleGain, TurboWhistlePitchMin and TurboWhistlePitchMax are then ignored (Reactor* values replace them; TurboWhistlePitch still scales the pitch). 0 does NOT silence it: the slot reverts to the old spool-driven turbo whistle and plays turbine_high as a whistle at TurboWhistleGain; to silence it, set ReactorGain to 0 instead (or clear TurboWhistleAssetId)."}, {"key": "ReactorGain", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.16}, {"key": "ReactorGain_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Reactor whine level at full load; while ReactorEnabled is 1 it replaces TurboWhistleGain. Raising it makes the sci-fi layer louder against the engine; 0 silences it (the way to turn the reactor off)."}, {"key": "ReactorLoadFloor", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.25}, {"key": "ReactorLoadFloor_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Share (0..1) of the reactor level kept off throttle. Raising it keeps the whine steady when coasting; 0 lets it vanish when you lift."}, {"key": "ReactorFullMph", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 200}, {"key": "ReactorFullMph_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Road speed (mph) where the reactor reaches its top pitch. Raising it makes the pitch climb more slowly with speed; lowering it tops out sooner."}, {"key": "ReactorPitchMin", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.7}, {"key": "ReactorPitchMin_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Reactor pitch (playback speed) at standstill; replaces TurboWhistlePitchMin while ReactorEnabled is 1. Raising it starts the whine higher; lowering it starts deeper."}, {"key": "ReactorPitchMax", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1.4}, {"key": "ReactorPitchMax_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Reactor pitch at ReactorFullMph; replaces TurboWhistlePitchMax while ReactorEnabled is 1. Raising it gives a higher scream at speed; set equal to ReactorPitchMin for a fixed pitch."}, {"key": "ReactorChirpDepth", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.03}, {"key": "ReactorChirpDepth_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Pitch dip (fraction) the reactor takes on each shift. Raising it makes a more obvious capacitor chirp; 0 removes it."}, {"key": "ReactorChirpSeconds", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.08}, {"key": "ReactorChirpSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Length (s) of the shift chirp. Raising it makes a slower swoop; lowering it a quick blip."}, {"key": "ReactorOverdriveGain", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.4}, {"key": "ReactorOverdriveGain_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Extra reactor level (fraction) while boosting past top-gear redline (Overdrive). Raising it makes Overdrive scream louder; 0 adds nothing."}, {"key": "SpinStrainGain", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1}, {"key": "SpinStrainGain_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "How strongly a spin-out (FeelSpin) drives the stabiliser strain sound. Raising it makes spins groan sooner and louder; 0 leaves the strain (and its engine duck) on sideways slip only."}, {"key": "SpinDuckScale", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1}, {"key": "SpinDuckScale_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Share (0..1) of the spin strain that also ducks the engine (by up to SlipDuckDb). Lowering it keeps the free-revving engine audible under a loud spin groan; 0 means a spin never ducks the engine (sideways slip still does)."}, {"key": "SciFiRpmShare", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0}, {"key": "SciFiRpmShare_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Share (0..1) of rpm in the sci-fi line (turbine pair, boost loop and boost body pitch). 0 keeps them smooth with road speed like an electric motor; 1 makes them saw-tooth with the gears."}, {"key": "RemoteGearsEnabled", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1}, {"key": "RemoteGearsEnabled_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Switch (0/1). 1: other players' cars with a gearbox derive gear and rpm from their speed, so their engine pitch steps through the gears (no network change). 0: they keep the old smooth speed rev."}, {"key": "RemoteVoiceLowFraction", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.4}, {"key": "RemoteVoiceLowFraction_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Fraction of redline the lowest in-gear voice of another car covers: with the idle voice kept, the highest loop that can still pitch down to it; otherwise the loop nearest it. Raising it sharpens the top end; lowering it gives more low-mid body."}, {"key": "RemoteVoiceHighFraction", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1}, {"key": "RemoteVoiceHighFraction_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Fraction of redline the highest of another car's engine voices sits at. Lowering it moves the voices toward the mid range."}, {"key": "RemoteIdleVoice", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1}, {"key": "RemoteIdleVoice_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Switch (0/1). 1: another car with a gearbox keeps its idle loop as one of its three voices (fading out between 1.2x and 1.8x idle rpm), so a parked or idling car, including your own after you get out, sounds like idle; the other two cover the gears (V10: On5000 and On8000). 0: all three voices cover the gears and an idling car plays the lowest one at its pitch floor (a low on-load drone)."}, {"key": "ShiftThunk1AssetId", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": ""}, {"key": "ShiftThunk1AssetId_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Roblox audio id for the first shift clunk (dry clack-thump, alternates with ShiftThunk2). Blank is silent and creates no player."}, {"key": "ShiftThunk1Gain", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.5}, {"key": "ShiftThunk1Gain_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Level of the first shift clunk (dry clack-thump, alternates with ShiftThunk2) at full shift strength. Raising it makes it louder; 0 silences it."}, {"key": "ShiftThunk1Pitch", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1}, {"key": "ShiftThunk1Pitch_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Playback speed of the first shift clunk (dry clack-thump, alternates with ShiftThunk2). Raising it makes it higher and shorter; lowering it deeper and longer."}, {"key": "ShiftThunk2AssetId", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": ""}, {"key": "ShiftThunk2AssetId_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Roblox audio id for the second shift clunk (alternates with ShiftThunk1). Blank is silent and creates no player."}, {"key": "ShiftThunk2Gain", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.5}, {"key": "ShiftThunk2Gain_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Level of the second shift clunk (alternates with ShiftThunk1) at full shift strength. Raising it makes it louder; 0 silences it."}, {"key": "ShiftThunk2Pitch", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1}, {"key": "ShiftThunk2Pitch_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Playback speed of the second shift clunk (alternates with ShiftThunk1). Raising it makes it higher and shorter; lowering it deeper and longer."}, {"key": "ShiftVent1AssetId", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": ""}, {"key": "ShiftVent1AssetId_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Roblox audio id for the first hard-upshift vent crackle (alternates with ShiftVent2; replaces the pop crackle when filled). Blank is silent and creates no player."}, {"key": "ShiftVent1Gain", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.55}, {"key": "ShiftVent1Gain_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Level of the first hard-upshift vent crackle (alternates with ShiftVent2; replaces the pop crackle when filled) at full shift strength. Raising it makes it louder; 0 silences it."}, {"key": "ShiftVent1Pitch", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1}, {"key": "ShiftVent1Pitch_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Playback speed of the first hard-upshift vent crackle (alternates with ShiftVent2; replaces the pop crackle when filled). Raising it makes it higher and shorter; lowering it deeper and longer."}, {"key": "ShiftVent2AssetId", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": ""}, {"key": "ShiftVent2AssetId_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Roblox audio id for the second hard-upshift vent crackle (alternates with ShiftVent1). Blank is silent and creates no player."}, {"key": "ShiftVent2Gain", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 0.55}, {"key": "ShiftVent2Gain_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Level of the second hard-upshift vent crackle (alternates with ShiftVent1) at full shift strength. Raising it makes it louder; 0 silences it."}, {"key": "ShiftVent2Pitch", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": 1}, {"key": "ShiftVent2Pitch_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Audio", "VehicleProfiles", "EXOTIC_V10_AUDIO"], "value": "Playback speed of the second hard-upshift vent crackle (alternates with ShiftVent1). Raising it makes it higher and shorter; lowering it deeper and longer."}, {"key": "ChaseDrivetrainEnabled", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 1}, {"key": "ChaseDrivetrainEnabled_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "1 turns on the drivetrain camera cues (spin hold, shift nod and FOV pulse, limiter shimmer) for cars with a class drivetrain; 0 gives exactly the camera from before."}, {"key": "ChaseSpinModeEnabled", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 1}, {"key": "ChaseSpinModeEnabled_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "1 holds the view steady while the car spins; 0 lets the camera swing round with the car as before."}, {"key": "ChaseSpinEnterLevel", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 0.2}, {"key": "ChaseSpinEnterLevel_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "Needs a bigger spin (FeelSpin 0..1) before the camera holds its view; 0 holds it on the slightest spin."}, {"key": "ChaseSpinExitLevel", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 0.1}, {"key": "ChaseSpinExitLevel_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "Releases the held spin view earlier as the spin dies down; 0 keeps holding until the spin has fully stopped."}, {"key": "ChaseSpinEaseInSeconds", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 0.15}, {"key": "ChaseSpinEaseInSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "Blends into the held spin view more gently; near 0 snaps straight into it."}, {"key": "ChaseSpinEaseOutSeconds", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 0.8}, {"key": "ChaseSpinEaseOutSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "Returns the camera behind the car more slowly after a spin (the spin yaw-rate cap relaxes over this time); near 0 swings back at the normal camera follow speed, with no cap."}, {"key": "ChaseSpinTravelMinStuds", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 12}, {"key": "ChaseSpinTravelMinStuds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "The held spin view follows the direction of travel only at a higher speed (studs/s); 0 always follows travel."}, {"key": "ChaseSpinTravelFadeStuds", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 6}, {"key": "ChaseSpinTravelFadeStuds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "Fades travel-following in over a wider speed band above ChaseSpinTravelMinStuds; 0 switches it on at once."}, {"key": "ChaseSpinTravelResponse", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 3}, {"key": "ChaseSpinTravelResponse_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "Turns the held spin view toward the direction of travel faster; 0 never turns it."}, {"key": "ChaseSpinYawRateMax", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 1.5}, {"key": "ChaseSpinYawRateMax_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "Lets the camera turn faster while the car spins (rad/s, from the first spin frame until the ease-out begins); lower keeps the view calmer, 0 is treated as 0.05 (almost still)."}, {"key": "ChaseShiftMinThrottle", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 0.5}, {"key": "ChaseShiftMinThrottle_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "Needs more throttle before an upshift nods the camera and pulses the FOV; 0 does it on every upshift (never on downshifts)."}, {"key": "ChaseShiftNodDegrees", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 1.0}, {"key": "ChaseShiftNodDegrees_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "Deeper camera nod on an upshift under load (degrees at full shift strength); 0 turns the nod off."}, {"key": "ChaseShiftNodOmega", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 9}, {"key": "ChaseShiftNodOmega_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "Makes the upshift nod quicker and snappier; lower values give a slower, softer nod."}, {"key": "ChaseShiftFovDegrees", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 1.2}, {"key": "ChaseShiftFovDegrees_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "Bigger field-of-view pulse on an upshift under load (positive widens, negative narrows); 0 turns the pulse off."}, {"key": "ChaseShiftFovOmega", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 10}, {"key": "ChaseShiftFovOmega_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "Makes the upshift FOV pulse shorter and sharper; lower values make it longer and softer."}, {"key": "ChaseLaunchKickStudsPerSecond", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 6}, {"key": "ChaseLaunchKickStudsPerSecond_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "Throws the camera back harder on a launch shift from a standstill; 0 turns the kick off."}, {"key": "ChaseLimiterShimmerDegrees", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 0.08}, {"key": "ChaseLimiterShimmerDegrees_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "Stronger roll buzz while the engine bounces off the rev limiter (never in neutral or on a shift cut); 0 turns it off."}, {"key": "ChaseLimiterShimmerHz", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 12}, {"key": "ChaseLimiterShimmerHz_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "Faster limiter buzz; lower values give a slower wobble."}, {"key": "ChaseLimiterHoldSeconds", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 0.15}, {"key": "ChaseLimiterHoldSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "Keeps the limiter buzz going longer after each limiter bounce; 0 turns the buzz off."}, {"key": "ChaseLimiterShimmerResponse", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": 20}, {"key": "ChaseLimiterShimmerResponse_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "Camera"], "value": "Limiter buzz fades in and out faster; lower values ease it in and out."}, {"key": "DrivetrainVFXEnabled", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 1}, {"key": "DrivetrainVFXEnabled_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "1 turns on the drivetrain effects (jets follow engine load, shift vent flame, spin stutter and dust, thrust-slip wash, strain shake) for cars with a class drivetrain; 0 gives exactly the effects from before."}, {"key": "DrivetrainThrustLoadEnabled", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 1}, {"key": "DrivetrainThrustLoadEnabled_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "1 makes the thrust jets follow engine load in a forward gear, so shift and limiter cuts dim them; 0 keeps them on the raw throttle as before while the other drivetrain effects stay on."}, {"key": "DrivetrainThrustReleaseSeconds", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 0.15}, {"key": "DrivetrainThrustReleaseSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Thrust jets fade more slowly when engine load drops, so shift and limiter cuts show less; values under 0.08 act as 0.08. With the throttle held a cut only dims the jets, never switches them off."}, {"key": "ShiftVentMinStrength", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 0.7}, {"key": "ShiftVentMinStrength_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Only harder upshifts (FeelShiftStrength 0..1, which already includes the class FeelGearing dial) fire a vent flame; 0 fires one on every upshift of any strength (none at FeelGearing 0)."}, {"key": "ShiftVentCount", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 10}, {"key": "ShiftVentCount_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Bigger vent flame burst on a hard upshift (particles at full strength); 0 turns the vent flame off."}, {"key": "ShiftVentPopStrength", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 0.6}, {"key": "ShiftVentPopStrength_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Hotter vent flame and brighter flash; it is multiplied by the shift strength, so the backfire flame tongue needs ShiftVentPopStrength x strength of 0.8 or more (never at the default 0.6); 0 is the smallest crackle."}, {"key": "ShiftVentFlashSeconds", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 0.08}, {"key": "ShiftVentFlashSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Longer vent flash after a hard upshift; 0 is the shortest flash."}, {"key": "ShiftVentFlashGain", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 1.4}, {"key": "ShiftVentFlashGain_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Brighter vent flash on cars without the Exotic V2 effects; 1 adds no extra brightness."}, {"key": "SpinStutterHz", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 9}, {"key": "SpinStutterHz_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Stabiliser jets alternate faster while the car spins (a brightness pulse, never on/off); 0 holds them steady."}, {"key": "SpinStutterMinSpin", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 0.2}, {"key": "SpinStutterMinSpin_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "A bigger spin (FeelSpin 0..1) is needed before the spin effects start; 0 reacts to the smallest spin."}, {"key": "SpinStutterFullSpin", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 0.6}, {"key": "SpinStutterFullSpin_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Spin effects reach full strength only in a bigger spin; at or below SpinStutterMinSpin they switch straight to full."}, {"key": "SpinStutterFloor", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 0.45}, {"key": "SpinStutterFloor_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Shallower stutter: the dim phase of each jet stays brighter; 1 means no pulse, 0 dims each side almost out."}, {"key": "SpinJetLevel", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 1}, {"key": "SpinJetLevel_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Stronger stabiliser jets during a spin; 0 turns the spin jets off."}, {"key": "SpinFadeSeconds", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 0.25}, {"key": "SpinFadeSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Spin effects linger longer after the spin ends; 0 stops them at once."}, {"key": "SpinDustLevel", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 0.6}, {"key": "SpinDustLevel_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "More hover dust during a spin (templates driven by HoverDust; no effect on Exotic V2 cars, whose dust has its own ExoticV2Dust tuning); 0 adds none."}, {"key": "SpinDustBurstSeconds", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 0.25}, {"key": "SpinDustBurstSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Fewer ground-wash bursts during a spin (seconds between bursts); small values give a near continuous wash."}, {"key": "SpinDustBurstCount", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 5}, {"key": "SpinDustBurstCount_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Bigger ground-wash bursts during a spin (particles at full spin); 0 turns them off. On Exotic V2 every burst also gives the same small hover-jet surge whatever the count, and about 6 or more also fires the landing ring."}, {"key": "ThrustSlipMin", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 0.1}, {"key": "ThrustSlipMin_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "More thrust slip (FeelThrustSlip 0..1) is needed before the launch effects show; 0 shows them on any slip."}, {"key": "ThrustSlipFull", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 0.6}, {"key": "ThrustSlipFull_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Launch effects reach full strength only at more slip; at or below ThrustSlipMin they switch straight to full."}, {"key": "ThrustSlipDustLevel", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 0.5}, {"key": "ThrustSlipDustLevel_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "More hover dust while the thrust slips (templates driven by HoverDust; no effect on Exotic V2 cars, whose dust has its own ExoticV2Dust tuning); 0 adds none."}, {"key": "ThrustSlipWashSeconds", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 0.2}, {"key": "ThrustSlipWashSeconds_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Fewer ground-wash bursts while the thrust slips (seconds between bursts); small values give a near continuous wash."}, {"key": "ThrustSlipWashCount", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 5}, {"key": "ThrustSlipWashCount_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Bigger launch ground wash while the thrust slips (particles at full slip); 0 turns it off. On Exotic V2 every burst also gives the same small hover-jet surge whatever the count, and about 6 or more also fires the landing ring."}, {"key": "StrainRpmStart", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 0.96}, {"key": "StrainRpmStart_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "The jets start shaking only closer to the redline (fraction of redline rpm); lower shakes earlier in every gear, 1 only on the limiter."}, {"key": "StrainOverdriveLevel", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 0.6}, {"key": "StrainOverdriveLevel_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "More jet shake in Overdrive (boosting past top-gear redline); 0 gives none."}, {"key": "StrainJitter", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 0.12}, {"key": "StrainJitter_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Stronger jet shake near the limiter and in Overdrive (share of thrust, at most 0.5); 0 turns the shake off."}, {"key": "StrainHz", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": 16}, {"key": "StrainHz_RaisingThisDoes", "path": ["ReplicatedStorage", "Config", "Vehicles", "StabiliserVFX"], "value": "Faster jet shake; lower values give a slow flutter."}], "base": "scripts/drivetrain_feel/", "instances": [{"attributes": {"DrivetrainFeelInstalled": true, "Enabled": 1, "Enabled_RaisingThisDoes": "1 = classes with a folder here use the drivetrain; 0 = every class drives exactly as before (instant recovery).", "Notes": "Drivetrain feel per vehicle class (scripts/drivetrain_feel/CONTRACT.md). Each child Folder is named after a CategoryId (exotic, bruiser, muscle) and switches the gearbox, weight and spin-out on for that class; a class with no folder drives exactly as before. To add a class: duplicate the exotic folder, rename the copy to the CategoryId, and retune it (start with the Feel* dials, then GearRatios, RedlineRpm and TorqueCurve). No code change is needed. Enabled 0 here switches every class off at once; Enabled 0 on a class folder switches only that class off."}, "children": [{"attributes": {"BoostShapeEnabled": 1, "BoostShapeEnabled_RaisingThisDoes": "1 = boost fades with speed so the boosted top speed stays today's; 0 = full boost at every speed (the speed guard still holds the top).", "BoostShareMin": 0.15, "BoostShareMin_RaisingThisDoes": "Keeps more boost near the boosted top speed (lower bound of the fade); 1 = no fade.", "BrakeDecel": 70, "BrakeDecel_RaisingThisDoes": "Stronger brakes at FeelWeight 1 (studs/s^2 at the reference brake stat). FeelWeight 0 uses today's brakes instead.", "BrakeFactorMax": 1.4, "BrakeFactorMax_RaisingThisDoes": "Strongest cars may brake harder (upper clamp of the braking stat factor).", "BrakeFactorMin": 0.75, "BrakeFactorMin_RaisingThisDoes": "Weakest cars brake harder (lower clamp of the braking stat factor).", "BrakeForceExponent": 0.35, "BrakeForceExponent_RaisingThisDoes": "Braking stat matters more for brake strength. 0 = every car brakes the same.", "CruiseThrottleMin": 0.05, "CruiseThrottleMin_RaisingThisDoes": "More throttle needed before any cruise upshift; below it no upshift at all (except off the limiter).", "DigitalCruiseDutyMax": 0.7, "DigitalCruiseDutyMax_RaisingThisDoes": "Heavier tapping still counts as cruising (averaged throttle duty at or below this short-shifts; a held throttle is 1). 0 = never.", "DigitalCruiseEnabled": 1, "DigitalCruiseEnabled_RaisingThisDoes": "1 = with keyboard or touch, tapping the throttle at a steady speed short-shifts up a gear, so the engine does not drone near redline; 0 = only the instant 0/1 throttle picks the gear.", "DigitalCruiseLand": 0.5, "DigitalCruiseLand_RaisingThisDoes": "A cruise short-shift must land at higher revs (fraction of redline; UpshiftMinLand also applies). Keep it above KickdownBelowFraction so the next tap does not kick back down. 0 = UpshiftMinLand only.", "DigitalCruiseSteadyMph": 3, "DigitalCruiseSteadyMph_RaisingThisDoes": "Speed may wander further from its average (mph) and still count as steady for a cruise short-shift. 0 = only a perfectly steady speed.", "DigitalCruiseUpshift": 0.6, "DigitalCruiseUpshift_RaisingThisDoes": "A cruising car on keyboard or touch holds its gear to higher revs before it short-shifts (fraction of redline).", "DigitalDutySeconds": 1.5, "DigitalDutySeconds_RaisingThisDoes": "The averaged throttle duty and the steady-speed average follow more slowly (seconds), so a cruise needs a longer steady spell before it short-shifts. Minimum 0.05.", "DownshiftBlendSeconds": 0.08, "DownshiftBlendSeconds_RaisingThisDoes": "Slower rev-matched rise after a downshift (no torque cut on downshifts). Minimum 0.01.", "DownshiftBrakeLand": 0.82, "DownshiftBrakeLand_RaisingThisDoes": "Braking downshifts happen earlier, landing at up to this fraction of redline (more engine braking, more blips).", "DownshiftCoastFraction": 0.3, "DownshiftCoastFraction_RaisingThisDoes": "Coasting downshifts happen at higher rpm (fraction of redline). 0 = no coasting downshifts.", "DownshiftCoastLand": 0.65, "DownshiftCoastLand_RaisingThisDoes": "Coasting and lugging downshifts may land at a higher rpm (fraction of redline).", "DriftAssistPlateauShare": 0.9, "DriftAssistPlateauShare_RaisingThisDoes": "Drift engine push follows the engine's full first-gear pull more than the current gear's thrust (0-1), so drifts in high gears keep today's push. 0 = the push follows the current gear's thrust only.", "DriftCapExempt": 1, "DriftCapExempt_RaisingThisDoes": "1 = drifts keep today's uncapped grip and yaw (drift lines unchanged), weighted by DriftExemptGain and DriftYawExempt; 0 = the grip limit and the yaw inertia also apply in drifts.", "DriftExemptGain": 4, "DriftExemptGain_RaisingThisDoes": "The drift's own grip and yaw take over sooner as a drift builds (exemption weight = drift blend x this, at most 1), so a drift entry does not run into the grip limit. 0 = no exemption; 1 = it follows the drift blend.", "DriftHoldDownshift": 1, "DriftHoldDownshift_RaisingThisDoes": "1 = inside a drift the gearbox may step down one gear at a time (when the lower gear lands at or below DownshiftBrakeLand), so a drift does not bog in a high gear; 0 = the gear is held for the whole drift.", "DriftYawExempt": 1, "DriftYawExempt_RaisingThisDoes": "Share of the drift exemption taken off the yaw inertia (0-1): 1 = drift yaw responds exactly as today; lower gives drifts some yaw weight. 0 = drifts keep the full yaw inertia.", "Enabled": 1, "Enabled_RaisingThisDoes": "1 = this class uses the drivetrain (gearbox, weight, spin-out, rpm HUD); 0 = it drives, sounds and displays exactly as before.", "EngineBrakeDecel": 1.5, "EngineBrakeDecel_RaisingThisDoes": "Stronger engine braking on a lift (studs/s^2 in top gear, more in low gears; x FeelEngineBrake). 0 = none.", "EngineFallScale": 1.5, "EngineFallScale_RaisingThisDoes": "Revs fall more slowly than they rise (x EngineRiseSeconds). 1 = same speed up and down.", "EngineRiseSeconds": 0.06, "EngineRiseSeconds_RaisingThisDoes": "Revs rise more lazily (heavier flywheel feel); falls scale with it through EngineFallScale. Minimum 0.01.", "FeelAcceleration": 1, "FeelAcceleration_RaisingThisDoes": "More engine thrust in every gear (quicker 0-60 and mid-range); top speed stays today's. Range 0.5-1.5.", "FeelEngineBrake": 1, "FeelEngineBrake_RaisingThisDoes": "Stronger slowing when you lift off, more in low gears. 0 = coasting is only drag and rolling resistance (range 0-2).", "FeelGearing": 1, "FeelGearing_RaisingThisDoes": "Gears felt more: bigger torque steps around the same average pull (pace unchanged), longer and deeper shift cuts, snappier rev drops, stronger shift cues. 0 = CVT-smooth with no cut (range 0-2).", "FeelGrip": 1, "FeelGrip_RaisingThisDoes": "Higher cornering grip limit and more traction off the line (less wheelspin). Range 0.6-1.6.", "FeelSpin": 1, "FeelSpin_RaisingThisDoes": "Spins more readily and more violently: scales the spin target, the spin push and the no-gesture hold cap (above 1 a held lock can wiggle harder or spin). 0 = it never spins (range 0-2.5).", "FeelWeight": 1, "FeelWeight_RaisingThisDoes": "Heavier car: more yaw inertia, slower steering build-up on keys and touch, slower grip build, more pitch and roll, longer braking. 0 = today's light, instant feel (range 0-2.5).", "GearCount": 7, "GearCount_RaisingThisDoes": "More forward gears are used (up to the number of GearRatios, at most 9); fewer gears give longer, bigger steps.", "GearRatios": "3.15,2.18,1.66,1.33,1.10,0.93,0.80", "GearRatios_RaisingThisDoes": "Gear ratios, first to top, comma separated. Wider gaps = bigger rev drops and torque steps; the gear speeds come from each car's own top speed, so only the ratios between gears matter.", "GearTorqueExponent": 0.8, "GearTorqueExponent_RaisingThisDoes": "Bigger drop in thrust in each higher gear (more real, slower top-end pull). 0 = the same thrust in every gear.", "GripRelaxStuds": 2, "GripRelaxStuds_RaisingThisDoes": "Grip builds over more travel when the car starts to slide (looser, heavier feel; x FeelWeight). 0 = instant.", "HudRedlineSweep": 0.87, "HudRedlineSweep_RaisingThisDoes": "Redline sits further round the gauge arc (fraction of the sweep); the limiter is just past it.", "HudShiftLeadSeconds": 0.25, "HudShiftLeadSeconds_RaisingThisDoes": "Shift light comes on earlier before a planned upshift (seconds of rpm climb). 0 = only at the shift point.", "HudShiftMinFraction": 0.85, "HudShiftMinFraction_RaisingThisDoes": "Shift light only for upshifts planned nearer redline (fraction); 0 = also for cruise short-shifts.", "HudWarmBandFraction": 0.12, "HudWarmBandFraction_RaisingThisDoes": "Warm light starts further below the flash point (fraction of redline). 0 = no warm stage.", "IdleRpm": 1100, "IdleRpm_RaisingThisDoes": "Higher idle and lowest rpm (gauge, sound); 0 is not allowed (minimum 300).", "ImpactYawKick": 0.6, "ImpactYawKick_RaisingThisDoes": "Hits off the car's centre line turn it more (rad/s per 100 studs/s of impact). 0 = impacts never turn the car.", "KickdownBelowFraction": 0.45, "KickdownBelowFraction_RaisingThisDoes": "Kickdown also fires at higher rpm (fraction of redline). 0 = no kickdown.", "KickdownHoldSeconds": 0.12, "KickdownHoldSeconds_RaisingThisDoes": "Full throttle must be held longer before a kickdown (fewer accidental kickdowns). 0 = instant.", "KickdownLand": 0.88, "KickdownLand_RaisingThisDoes": "Kickdown may drop to a lower gear, landing at up to this fraction of redline (harder kick).", "KickdownThrottle": 0.95, "KickdownThrottle_RaisingThisDoes": "More throttle needed for a kickdown (several gears at once).", "LateralCapG": 3.4, "LateralCapG_RaisingThisDoes": "Higher cornering grip limit (g): tighter fast corners, later understeer. Lower = heavier, wider lines.", "LateralCapGripExponent": 0.25, "LateralCapGripExponent_RaisingThisDoes": "LateralGrip stat matters more for the grip limit. 0 = every car has the same limit.", "LateralCurveShape": 1.4, "LateralCurveShape_RaisingThisDoes": "Grip falls away more once past the limit (sharper peak). 1 = grip never drops past the limit (1-1.9).", "LaunchRpmFraction": 0.5, "LaunchRpmFraction_RaisingThisDoes": "Higher launch and power-brake revs in first gear (clutch slip, fraction of redline). 0 = first gear follows road speed from idle.", "LiftHoldSeconds": 0.8, "LiftHoldSeconds_RaisingThisDoes": "Holds the gear longer after a lift before a part-throttle upshift (less churn when tapping). 0 = no hold. Does not block the digital cruise upshift.", "LimiterCutSeconds": 0.045, "LimiterCutSeconds_RaisingThisDoes": "Longer limiter cuts (harder, slower bounce). 0 = the limiter holds without cutting.", "LimiterHysteresisRpm": 150, "LimiterHysteresisRpm_RaisingThisDoes": "Deeper limiter bounce: the rpm drops further below redline in each cut. 0 = minimal bounce.", "LimiterOnSeconds": 0.03, "LimiterOnSeconds_RaisingThisDoes": "Longer drive bursts between limiter cuts (slower bounce). Minimum 0.005.", "LimiterRpm": 8600, "LimiterRpm_RaisingThisDoes": "Limiter sits further above redline (flare and limiter peak); clamped to 1-1.2 x RedlineRpm.", "NeutralRevEnabled": 1, "NeutralRevEnabled_RaisingThisDoes": "1 = the engine revs in neutral with the throttle during a countdown (no force); 0 = idles until GO.", "NeutralRevTarget": 1.02, "NeutralRevTarget_RaisingThisDoes": "Higher neutral revs at full throttle (fraction of redline); above 1 bounces the limiter. 0 = stays at idle.", "Notes": "Exotic V10 hybrid, 7-speed automatic. Tune the Feel dials first (1 = the designed feel): FeelWeight (mass: yaw inertia, steering build-up, grip build, pitch and roll, braking; 0 = today's light instant feel), FeelGearing (how much you feel the gears; 0 = CVT-smooth, no cut), FeelAcceleration (thrust in every gear; top speed stays today's), FeelGrip (cornering limit and traction), FeelSpin (how readily and hard it spins; 0 = never), FeelEngineBrake (lift-off slowing; 0 = drag and rolling only). Every number has a _RaisingThisDoes note.", "OverdriveEnabled": 1, "OverdriveEnabled_RaisingThisDoes": "1 = boosting past top-gear redline pins the engine at redline with no limiter cut (Overdrive); 0 = it hits the limiter.", "PitchDamping": 0.6, "PitchDamping_RaisingThisDoes": "Less bounce on pitch and roll; lower = more overshoot.", "PitchDegreesPerG": 2.4, "PitchDegreesPerG_RaisingThisDoes": "More nose-up under acceleration and nose-down under braking and shift cuts (degrees per g, x FeelWeight). 0 = level.", "PitchMaxDegrees": 5, "PitchMaxDegrees_RaisingThisDoes": "Allows a larger pitch angle (degrees). 0 = no pitch.", "PitchOmega": 9, "PitchOmega_RaisingThisDoes": "Pitch and roll follow quicker and snappier (rad/s); lower = slower, floatier body motion.", "PowerBrakeDumpSlip": 0.5, "PowerBrakeDumpSlip_RaisingThisDoes": "Harder burnout and more spin on a power-brake release (extra thrust slip, fading over the window). 0 = no dump.", "PowerBrakeEnabled": 1, "PowerBrakeEnabled_RaisingThisDoes": "1 = holding forward and brake at a standstill, then releasing brake, dumps the revs (burnout start); 0 = off.", "PowerBrakeMinHold": 0.3, "PowerBrakeMinHold_RaisingThisDoes": "Forward and brake must be held together longer before the release counts (seconds).", "RedlineRpm": 8500, "RedlineRpm_RaisingThisDoes": "Higher redline: the rpm scale stretches (gauge, sound, shift points scale with it); gear speeds do not change.", "RollDegreesPerG": 0.9, "RollDegreesPerG_RaisingThisDoes": "More body roll away from the turn from cornering g (degrees per g, x FeelWeight). 0 = off; negative leans into the turn instead. The steering bank is separate and unchanged.", "RollMaxDegrees": 3, "RollMaxDegrees_RaisingThisDoes": "Allows a larger body roll angle (degrees). 0 = no roll.", "RollingDecel": 0.8, "RollingDecelPerStud": 0.004, "RollingDecelPerStud_RaisingThisDoes": "More speed-proportional resistance: coasts down sooner at speed. 0 = none (top speed is kept).", "RollingDecel_RaisingThisDoes": "More constant rolling resistance (studs/s^2): coasts down sooner. 0 = none (top speed is kept by re-deriving drag).", "ShiftBlendSeconds": 0.06, "ShiftBlendSeconds_RaisingThisDoes": "Slower thrust return after the upshift cut (x FeelGearing). 0 = thrust returns at once.", "ShiftCutSeconds": 0.06, "ShiftCutSeconds_RaisingThisDoes": "Longer torque cut on each upshift (x FeelGearing). 0 = no cut.", "ShiftCutTorque": 0.45, "ShiftCutTorque_RaisingThisDoes": "Share of thrust kept during the upshift cut: higher = gentler cut, 1 = no cut, 0 = full cut.", "ShiftMinIntervalSeconds": 0.25, "ShiftMinIntervalSeconds_RaisingThisDoes": "Longer minimum time between shifts (less hunting, slower gear changes). Minimum 0.05.", "ShiftRpmSeconds": 0.05, "ShiftRpmSeconds_RaisingThisDoes": "Slower rev drop after an upshift (divided by FeelGearing). Minimum 0.005.", "SlideGripFraction": 0.88, "SlideGripFraction_RaisingThisDoes": "Less thrust lost while the thrust slips (1 = slipping costs nothing; lower = burnouts are slower).", "SpeedGuardOverBoostTop": 1.03, "SpeedGuardOverBoostTop_RaisingThisDoes": "Lets the car go further past today's boosted top speed before the guard bites (1 = exactly today's).", "SpeedGuardStrength": 2, "SpeedGuardStrength_RaisingThisDoes": "Holds the boosted top speed harder above SpeedGuardOverBoostTop x boosted top. 0 = no guard.", "SpinAnalogRate": 4, "SpinAnalogRate_RaisingThisDoes": "Gamepad throttle must rise faster after a lift (per second, from under 0.3 to 0.9) to count as a stab; lower = easier stabs on a trigger.", "SpinBelowMph": 30, "SpinBelowMph_RaisingThisDoes": "Spins can start at higher speed (mph; full authority below it, then fading over SpinFadeMph).", "SpinBuildRate": 6, "SpinBuildRate_RaisingThisDoes": "Spins build faster (per second). 0 = never builds.", "SpinCatchRate": 8, "SpinCatchRate_RaisingThisDoes": "Lifting (under 0.3 throttle) or counter-steering catches the spin faster (per second).", "SpinDecayRate": 2.5, "SpinDecayRate_RaisingThisDoes": "Spins die down faster on their own (per second).", "SpinEnabled": 1, "SpinEnabled_RaisingThisDoes": "1 = low-speed spin-outs are possible; 0 = the car never spins.", "SpinFadeMph": 12, "SpinFadeMph_RaisingThisDoes": "Spin authority fades out over a wider speed band above SpinBelowMph.", "SpinFlickSeconds": 0.15, "SpinFlickSeconds_RaisingThisDoes": "The steering flick and the throttle stab may be further apart (either order) and still count as a stab: easier stabs. 0 = they must land on the same frame.", "SpinGripLoss": 0.85, "SpinGripLoss_RaisingThisDoes": "More sideways grip lost in a spin (0-1): the car slides further.", "SpinHoldCap": 0.35, "SpinHoldCap_RaisingThisDoes": "A bigger wiggle is allowed without a gesture (largest spin amount outside a stab or power-brake window, x FeelSpin, at most 1). 0 = only gestures spin.", "SpinMaxYawRate": 3.6, "SpinMaxYawRate_RaisingThisDoes": "Faster spin rotation allowed (rad/s; never above YawRateMax).", "SpinSettleSeconds": 0.3, "SpinSettleSeconds_RaisingThisDoes": "Car eases back to normal steering more slowly after a catch (seconds; the spin's own yaw dies at least as fast as 3 / this). 0 = snaps back.", "SpinSlipStart": 0.04, "SpinSlipStart_RaisingThisDoes": "More thrust slip needed before a spin can build (fewer spins).", "SpinSlipWidth": 0.08, "SpinSlipWidth_RaisingThisDoes": "Spin authority reaches full only at more thrust slip past SpinSlipStart.", "SpinStabDumpSlip": 0.3, "SpinStabDumpSlip_RaisingThisDoes": "Harder wheelspin and a bigger spin from a stab (extra thrust slip, fading over the spin window like the power-brake). 0 = a stab adds no slip.", "SpinStabNeedsFlick": 1, "SpinStabNeedsFlick_RaisingThisDoes": "1 = a stab also needs a steering flick (lock applied or reversed within SpinFlickSeconds of the throttle stab), so a lifted U-turn or pull-out with the wheel held never spins; 0 = a plain lift-and-stab with the lock held is enough.", "SpinStabSeconds": 0.4, "SpinStabSeconds_RaisingThisDoes": "Keyboard and touch: the throttle may come back (to 0.9 or more) longer after a lift and still count as a stab (seconds from the lift). 0 = only an instant re-press.", "SpinStabSteer": 0.8, "SpinStabSteer_RaisingThisDoes": "More steering lock needed for a stab and for the steering flick that goes with it (0-1).", "SpinStartGraceMph": 38, "SpinStartGraceMph_RaisingThisDoes": "After an anchored start or a DriveReady restart the grace also lasts until the car has gone faster than this (mph), whichever is later; spawning and R use the time only. 0 = time only.", "SpinStartGraceSeconds": 3, "SpinStartGraceSeconds_RaisingThisDoes": "Longer no-spin grace after a start, reset or unanchor (seconds).", "SpinSteerStart": 0.6, "SpinSteerStart_RaisingThisDoes": "More steering needed before a spin can build (0-1).", "SpinSteerWidth": 0.35, "SpinSteerWidth_RaisingThisDoes": "Spin authority reaches full only at more steering past SpinSteerStart.", "SpinThrustLoss": 0.35, "SpinThrustLoss_RaisingThisDoes": "More thrust lost in a spin (0-1).", "SpinTierFloor": 0.8, "SpinTierFloor_RaisingThisDoes": "Low-PI cars get more spin authority (share at TierStartPI; full at TierFullPI).", "SpinTouchScale": 0.5, "SpinTouchScale_RaisingThisDoes": "Touch players spin more readily (x spin target). 0 = no spins on touch.", "SpinWarnLevel": 0.25, "SpinWarnLevel_RaisingThisDoes": "The amber spin warning (HUD shift light 4) comes later, at a bigger spin amount (never below the hold cap + 0.05).", "SpinWindowSeconds": 0.9, "SpinWindowSeconds_RaisingThisDoes": "Spin window after a stab or power-brake lasts longer: a bigger spin can build. 0 = gestures do nothing.", "SpinYawAccel": 25, "SpinYawAccel_RaisingThisDoes": "Spins rotate the car harder (rad/s^2 at full